text:
Laboratorio: ¿qué modo domina en tu texto?


Laboratorio · se ejecuta en tu navegador

Pega un párrafo (un resumen, una introducción, el arranque de una charla). El laboratorio busca marcas típicas de cada modo de persuasión: cifras y conectores lógicos (logos), referencias a quien habla o a autoridades (ethos) y palabras valorativas o emocionales (pathos). Es una herramienta orientativa: la retórica no se reduce a contar palabras, pero ayuda a ver desequilibrios.

area = window.Lab.area
viewof texto_modos = area("Tu texto", {rows: 6, submit: "Analizar", value: "Cada año, miles de doctorandos abandonan su tesis antes de terminarla. En nuestro estudio con 1200 participantes de 14 universidades, encontramos que la falta de supervisión explica el 30 % del abandono; por tanto, mejorar la supervisión podría evitar cientos de abandonos dolorosos y costosos. Como investigadores con diez años de experiencia en este campo, proponemos tres medidas concretas."})
















{
  const t = texto_modos.toLowerCase();
  const cuenta = re =&gt; (t.match(re) || []).length;
  const logos = cuenta(/\d+([.,]\d+)?\s*%?|\b(por tanto|por lo tanto|porque|ya que|así que|en consecuencia|demuestra|muestra|indica|datos|resultados|evidencia|estudio|análisis|media|significativ\w*)\b/g);
  const ethos = cuenta(/\b(nuestro|nuestra|nuestros|nosotros|como investigador\w*|experiencia|expert\w*|según|universidad\w*|grupo|equipo|publicad\w*|revisad\w*)\b/g);
  const pathos = cuenta(/\b(miles|millones|vida|vidas|dolor\w*|grave\w*|urgente\w*|esperanza|miedo|crisis|devastador\w*|increíble|extraordinari\w*|sufr\w*|injust\w*|costos\w*|importante\w*|preocupante\w*|abandon\w*)\b/g);
  const tot = Math.max(1, logos + ethos + pathos), pc = v =&gt; Math.round(100 * v / tot);
  const fila = (n, v, c) =&gt; `&lt;tr&gt;&lt;td&gt;${n}&lt;/td&gt;&lt;td style="text-align:right"&gt;${v}&lt;/td&gt;&lt;td style="width:55%"&gt;&lt;div style="height:.8rem;border-radius:2px;background:${c};width:${pc(v)}%"&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;`;
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Modo&lt;/th&gt;&lt;th scope="col"&gt;Marcas&lt;/th&gt;&lt;th scope="col"&gt;&lt;span class="visually-hidden"&gt;Barra&lt;/span&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
   ${fila("Logos (razón, datos)", logos, "#2a78d6")}${fila("Ethos (credibilidad)", ethos, "#1baf7a")}${fila("Pathos (emoción, valores)", pathos, "#eb6834")}&lt;/tbody&gt;&lt;/table&gt;
   &lt;p class="small"&gt;${logos === 0 ? "No aparecen datos ni conectores lógicos: ¿en qué se apoya la afirmación? " : ""}${pathos === 0 ? "No hay ninguna marca de por qué importa: ¿lo entenderá alguien ajeno a tu campo? " : ""}${pathos &gt; logos ? "El pathos supera al logos: comprueba que la emoción no sustituye a la evidencia." : ""}&lt;/p&gt;`;
  return d;
}

Laboratorio: construye un argumento de Toulmin


Laboratorio · se ejecuta en tu navegador

Rellena las piezas con un argumento de tu investigación y pulsa Montar. El laboratorio dibuja el diagrama y te avisa de las piezas que faltan.

texto = window.Lab.texto
viewof tl = {
  const c = html`&lt;div&gt;&lt;/div&gt;`, campos = [["dato", "Datos", "En el ensayo, abandonó el 8 % con tutoría y el 15 % sin ella"], ["afirm", "Afirmación", "La tutoría semanal reduce el abandono del doctorado"],
    ["garantia", "Garantía", "La asignación fue aleatoria, así que la diferencia se debe a la tutoría"], ["respaldo", "Respaldo", "Los ensayos aleatorizados controlan la confusión"],
    ["cual", "Cualificador", "probablemente, en programas parecidos"], ["refut", "Refutación", "salvo que los abandonos se debieran a causas económicas"]];
  const ins = campos.map(([k, et, v]) =&gt; { const t = texto(et, {value: v}); t.addEventListener("input", e =&gt; e.stopPropagation()); c.append(t); return [k, t]; });
  const b = html`&lt;button type="button" class="btn btn-primary btn-sm mt-1"&gt;Montar&lt;/button&gt;`; c.append(b);
  const leer = () =&gt; Object.fromEntries(ins.map(([k, t]) =&gt; [k, t.value.trim()]));
  c.value = leer(); b.onclick = () =&gt; { c.value = leer(); c.dispatchEvent(new Event("input", {bubbles: true})); };
  return c;
}
















{
  const esc = s =&gt; (s || "").replace(/&/g, "&amp;").replace(/&lt;/g, "&lt;");
  const caja = (x, y, w, t, et, c) =&gt; `&lt;foreignObject x="${x}" y="${y}" width="${w}" height="74"&gt;&lt;div xmlns="http://www.w3.org/1999/xhtml" style="border:2px solid ${c};border-radius:8px;padding:4px 6px;font-size:11.5px;height:68px;overflow:hidden;background:var(--bs-body-bg)"&gt;&lt;strong&gt;${et}&lt;/strong&gt;&lt;br&gt;${esc(t) || "&lt;em&gt;(falta)&lt;/em&gt;"}&lt;/div&gt;&lt;/foreignObject&gt;`;
  const faltan = [["garantia", "la garantía"], ["cual", "el cualificador"], ["refut", "la refutación"], ["respaldo", "el respaldo"]].filter(([k]) =&gt; !tl[k]).map(x =&gt; x[1]);
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="0 0 620 260" width="100%" style="max-width:620px" role="img" aria-label="Diagrama de Toulmin del argumento"&gt;
   ${caja(5, 10, 180, tl.dato, "Datos", "#2a78d6")}
   &lt;line x1="185" y1="47" x2="430" y2="47" stroke="currentColor" stroke-width="1.5" marker-end="url(#fl)"/&gt;
   &lt;defs&gt;&lt;marker id="fl" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"&gt;&lt;path d="M0,0 L8,4 L0,8 z" fill="currentColor"/&gt;&lt;/marker&gt;&lt;/defs&gt;
   ${caja(435, 10, 180, (tl.cual ? tl.cual + ": " : "") + tl.afirm, "Afirmación (con cualificador)", "#eb6834")}
   &lt;line x1="307" y1="47" x2="307" y2="96" stroke="currentColor" stroke-dasharray="3 3"/&gt;
   ${caja(215, 96, 185, tl.garantia, "Garantía (porque…)", "#1baf7a")}
   &lt;line x1="307" y1="170" x2="307" y2="180" stroke="currentColor" stroke-dasharray="3 3"/&gt;
   ${caja(215, 180, 185, tl.respaldo, "Respaldo", "#8a5d00")}
   &lt;line x1="525" y1="84" x2="525" y2="140" stroke="currentColor" stroke-dasharray="3 3"/&gt;
   ${caja(435, 140, 180, tl.refut, "Refutación (salvo que…)", "#c0392b")}&lt;/svg&gt;
   &lt;p class="small"&gt;${faltan.length ? "Falta " + faltan.join(", ") + ". Sin garantía, el lector no sabe por qué los datos apoyan la afirmación." : "Argumento completo: ahora prueba a escribirlo en un solo párrafo."}&lt;/p&gt;`;
  return d;
}

Laboratorio: tu mensaje en ABT


Laboratorio · se ejecuta en tu navegador

Escribe las tres partes de tu mensaje. El laboratorio las une, cuenta las palabras (lo ideal es que quepa en unas 50) y señala problemas típicos.

texto = window.Lab.texto
viewof abt = {
  const c = html`&lt;div&gt;&lt;/div&gt;`, campos = [["y", "Y… (contexto conocido)", "Cada año miles de doctorandos empiezan su tesis con ilusión"],
    ["pero", "PERO… (el problema)", "casi un tercio la abandona antes de terminar, y no sabemos bien por qué"],
    ["portanto", "POR TANTO… (lo que hiciste o propones)", "seguimos a 1200 doctorandos durante cinco años para identificar qué apoyos marcan la diferencia"]];
  const ins = campos.map(([k, et, v]) =&gt; { const t = texto(et, {value: v}); t.addEventListener("input", e =&gt; { e.stopPropagation(); c.value = leer(); c.dispatchEvent(new Event("input", {bubbles: true})); }); c.append(t); return [k, t]; });
  const leer = () =&gt; Object.fromEntries(ins.map(([k, t]) =&gt; [k, t.value.trim()]));
  c.value = leer(); return c;
}
















{
  const frase = `${abt.y}, pero ${abt.pero}; por tanto, ${abt.portanto}.`.replace(/\s+/g, " ");
  const n = frase.split(/\s+/).filter(Boolean).length;
  const avisos = [];
  if (!abt.pero) avisos.push("Falta el PERO: sin tensión no hay historia, solo una lista (estructura «Y, y, y»).");
  if (/\b(y|además)\b/i.test(abt.pero) && abt.pero.split(/\s+/).length &lt; 5) avisos.push("El PERO parece otro «y»: plantea un problema, un vacío o una contradicción.");
  if (n &gt; 70) avisos.push(`Tiene ${n} palabras: intenta dejarlo en unas 50.`);
  if (/\b(\w+ción|\w+miento)\b.*\b(\w+ción|\w+miento)\b.*\b(\w+ción|\w+miento)\b/i.test(frase)) avisos.push("Muchos sustantivos abstractos (-ción, -miento): prueba con verbos.");
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;blockquote class="lab-cita" style="border-left:4px solid #2a78d6;padding-left:.8rem"&gt;${frase.replace(/&lt;/g, "&lt;")}&lt;/blockquote&gt;
   &lt;p&gt;${n} palabras. ${avisos.length ? "" : '&lt;span class="lab-bien" style="font-weight:600"&gt;Buena estructura.&lt;/span&gt;'}&lt;/p&gt;${avisos.map(a =&gt; `&lt;p class="lab-medio small" style="font-weight:600"&gt;${a}&lt;/p&gt;`).join("")}`;
  return d;
}

Laboratorio: mide tu discurso


Laboratorio · se ejecuta en tu navegador; tu texto no sale de él

Pega el guion de una charla. El laboratorio calcula cuánto durará a la velocidad que elijas, la longitud media de las frases, las frases demasiado largas para decirlas de un tirón y la legibilidad con el índice de Fernández Huerta (adaptación al español del de Flesch; más alto = más fácil).

area = window.Lab.area
rango = window.Lab.rango
viewof guion = area("Guion", {rows: 7, submit: "Analizar", value: "Imaginen que cada año miles de doctorandos empiezan su tesis con ilusión. Casi un tercio la abandona antes de terminar. Durante cinco años seguimos a mil doscientos doctorandos de catorce universidades españolas, midiendo cada seis meses su bienestar, su relación con la dirección y su productividad, con el objetivo de identificar qué factores, de entre todos los que la literatura había propuesto en las últimas dos décadas, predecían mejor el abandono. El resultado fue claro. La calidad de la supervisión pesaba más que la financiación."})
viewof ppm = rango("Velocidad (palabras por minuto)", [100, 180], {step: 5, value: 135})






























{
  const frases = guion.replace(/\s+/g, " ").split(/(?&lt;=[.!?…])\s+/).filter(f =&gt; f.trim());
  const palabras = guion.toLowerCase().match(/[a-záéíóúüñ]+/gi) || [];
  const silabas = w =&gt; { const g = w.toLowerCase().replace(/[^a-záéíóúüñ]/g, "").replace(/qu|gu(?=[eéií])/g, "q").match(/[iuü][aáeéoó]|[aáeéoó][iuü](?![aáeéoó])|[iu][iu]|[aáeéiíoóuúü]/g); return Math.max(1, (g || []).length); };
  const nP = palabras.length, nS = palabras.reduce((s, w) =&gt; s + silabas(w), 0), nF = Math.max(1, frases.length);
  const P = 100 * nS / nP, F = 100 * nF / nP, fh = 206.84 - 0.60 * P - 1.02 * F;
  const largas = frases.filter(f =&gt; (f.match(/\S+/g) || []).length &gt; 30);
  const mins = nP / ppm, mm = Math.floor(mins), ss = Math.round((mins - mm) * 60);
  const nivel = fh &gt;= 80 ? "fácil" : fh &gt;= 60 ? "normal" : fh &gt;= 40 ? "algo difícil" : "difícil";
  const d = html`&lt;div role="status"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;ul&gt;&lt;li&gt;${nP} palabras · duración estimada &lt;strong&gt;${mm} min ${String(ss).padStart(2, "0")} s&lt;/strong&gt; a ${ppm} palabras por minuto&lt;/li&gt;
   &lt;li&gt;${nF} frases · media de &lt;strong&gt;${(nP / nF).toFixed(1).replace(".", ",")}&lt;/strong&gt; palabras por frase&lt;/li&gt;
   &lt;li&gt;Legibilidad (Fernández Huerta): &lt;strong&gt;${fh.toFixed(0)}&lt;/strong&gt; · ${nivel}&lt;/li&gt;&lt;/ul&gt;
   ${largas.length ? `&lt;p class="lab-medio" style="font-weight:600"&gt;${largas.length} frase${largas.length &gt; 1 ? "s" : ""} de más de 30 palabras: difícil de decir y de seguir. Divídela.&lt;/p&gt;&lt;blockquote class="small"&gt;${largas[0].replace(/&lt;/g, "&lt;")}&lt;/blockquote&gt;` : '&lt;p class="lab-bien" style="font-weight:600"&gt;Ninguna frase supera las 30 palabras.&lt;/p&gt;'}
   &lt;p class="small"&gt;El recuento de sílabas es aproximado. Escribir para el oído pide frases más cortas que escribir para la vista.&lt;/p&gt;`;
  return d;
}

Laboratorio: cronómetro de ensayo


Laboratorio · se ejecuta en tu navegador

Ensaya en voz alta con tiempo real. Elige la duración y pulsa Empezar: el cronómetro avisa cuando llevas la mitad, cuando queda un 20 % y cuando se acaba.

viewof dur = rango("Duración de la charla (minutos)", [1, 20], {step: 1, value: 3})







{
  const c = html`&lt;div class="lab-crono"&gt;&lt;p class="lab-reloj" style="font-size:2.4rem;font-variant-numeric:tabular-nums;font-weight:600;margin:0" aria-live="off"&gt;0:00&lt;/p&gt;
    &lt;p class="lab-fase" role="status" aria-live="polite"&gt;Pulsa Empezar cuando comiences a hablar.&lt;/p&gt;
    &lt;div class="d-flex gap-2"&gt;&lt;button type="button" class="btn btn-primary btn-sm"&gt;Empezar&lt;/button&gt;&lt;button type="button" class="btn btn-outline-primary btn-sm"&gt;Parar&lt;/button&gt;&lt;/div&gt;&lt;/div&gt;`;
  const [reloj, fase, ini, fin] = [c.querySelector(".lab-reloj"), c.querySelector(".lab-fase"), ...c.querySelectorAll("button")];
  let t0 = null, id = null, avisos = new Set();
  const total = dur * 60;
  const tick = () =&gt; { const s = Math.floor((Date.now() - t0) / 1000); reloj.textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
    const msgs = [[0.5, "Mitad del tiempo: ¿vas por la mitad del contenido?"], [0.8, "Queda un 20 %: ve hacia la conclusión."], [1, "Tiempo cumplido: termina con tu mensaje principal."]];
    for (const [f, m] of msgs) if (s &gt;= total * f && !avisos.has(f)) { avisos.add(f); fase.textContent = m; }
    if (s &gt;= total * 1.1) { reloj.style.color = "#a52a1a"; } };
  ini.onclick = () =&gt; { clearInterval(id); t0 = Date.now(); avisos = new Set(); reloj.style.color = ""; fase.textContent = "Hablando…"; id = setInterval(tick, 250); };
  fin.onclick = () =&gt; { clearInterval(id); if (t0) fase.textContent = `Has hablado ${reloj.textContent} de ${dur}:00.`; };
  invalidation.then(() =&gt; clearInterval(id));
  return c;
}

Laboratorio · se ejecuta en tu navegador

En el enfoque afirmación-evidencia (Alley), cada diapositiva tiene como título una frase completa que dice la conclusión, y el cuerpo muestra la evidencia visual. Escribe un título y el laboratorio lo revisa.

textoR = window.Lab.texto
viewof tituloDiapo = textoR("Título de tu diapositiva", {value: "Resultados"})
















{
  const t = tituloDiapo.trim(), palabras = t.split(/\s+/).filter(Boolean), n = palabras.length;
  const generico = /^(introducción|resultados|metodología|método|métodos|conclusiones?|discusión|objetivos?|contexto|antecedentes|datos|análisis|agradecimientos)$/i.test(t.replace(/[.:]$/, ""));
  const verbo = palabras.some((w) =&gt; { const x = w.toLowerCase().replace(/[^a-záéíóúüñ]/g, ""); return ["es", "son", "fue", "fueron", "hay", "está", "están", "puede", "pueden", "reduce", "reducen", "aumenta", "aumentan", "mejora", "mejoran", "duplica", "triplica", "multiplica", "explica", "predice", "muestra", "muestran", "demuestra", "permite", "indica", "sugiere", "supera", "crece", "cae", "disminuye", "depende", "cambia", "funciona", "falla", "afecta", "baja", "sube", "tarda", "cuesta", "necesita", "requiere", "evita", "acelera", "frena", "mantiene", "genera"].includes(x) || (x.length &gt; 4 && /(aron|ieron|aban|ían|ará|erá|irá|arán|erán|irán)$/.test(x)); });
  const cifra = /\d/.test(t);
  const checks = [
    [!generico, "No es una etiqueta genérica («Resultados», «Metodología»…)."],
    [n &gt;= 6, "Tiene al menos 6 palabras: es una frase, no un tema."],
    [n &lt;= 20, "No pasa de 20 palabras (cabe en dos líneas)."],
    [verbo, "Contiene un verbo que afirma algo."],
    [cifra, "Incluye una cifra o un dato concreto (recomendable, no obligatorio)."]];
  const nota = checks.slice(0, 4).filter((c) =&gt; c[0]).length;
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;div class="p-3 border rounded mb-2" style="aspect-ratio:16/9;max-width:480px;display:flex;flex-direction:column"&gt;&lt;div style="font-size:1.25rem;font-weight:600;line-height:1.25"&gt;${t.replace(/[&&lt;&gt;]/g, "") || "(sin título)"}&lt;/div&gt;&lt;div class="mt-auto small text-body-secondary"&gt;[evidencia visual: gráfico, imagen o esquema]&lt;/div&gt;&lt;/div&gt;
  &lt;ul class="list-unstyled"&gt;${checks.map(([ok, txt], i) =&gt; `&lt;li&gt;${ok ? "✓" : i === 4 ? "○" : "✗"} ${txt}&lt;/li&gt;`).join("")}&lt;/ul&gt;
  &lt;p&gt;${nota === 4 ? "Buen título-afirmación: el público sabe qué debe recordar aunque no lea nada más." : "Prueba a reescribirlo como la conclusión de la diapositiva. Por ejemplo: «La tutoría entre iguales reduce el abandono del 18 % al 9 %»."}&lt;/p&gt;`;
  return d;
}

Laboratorio: la estructura de tu charla


Laboratorio · se ejecuta en tu navegador

Nancy Duarte describe las grandes charlas como un ir y venir entre lo que es (la situación actual) y lo que podría ser (el futuro que propones), que termina en una llamada a la acción y una nueva normalidad. Escribe los momentos de tu charla, uno por línea, empezando por ES: o PODRÍA:, y mira su perfil.

areaS = window.Lab.area
viewof momentos = areaS("Momentos de tu charla", {rows: 8, value: "ES: Cada año se pierden miles de horas buscando datos que ya existen\nPODRÍA: Imagina encontrarlos en un minuto\nES: Hoy están en PDF, sin licencia ni identificador\nPODRÍA: Con datos abiertos y FAIR, cualquiera los reutiliza\nES: Muchos equipos creen que publicar datos es caro\nPODRÍA: Publicar en un repositorio cuesta una tarde\nACCIÓN: Deposita tu próximo conjunto de datos en Zenodo\nNUEVA: Un grupo que comparte por defecto"})
















{
  const ls = momentos.split("\n").map((l) =&gt; l.trim()).filter(Boolean);
  const tipo = (l) =&gt; /^ES:/i.test(l) ? "es" : /^PODR[IÍ]A:/i.test(l) ? "podria" : /^ACCI[OÓ]N:/i.test(l) ? "accion" : /^NUEVA:/i.test(l) ? "nueva" : "otro";
  const pts = ls.map((l) =&gt; ({t: tipo(l), txt: l.replace(/^[^:]+:\s*/, "")}));
  const W = 560, H = 230, n = Math.max(pts.length, 2), x = (i) =&gt; 30 + i * (W - 60) / (n - 1), y = {es: 160, podria: 70, accion: 40, nueva: 100, otro: 115};
  const color = {es: "#52514e", podria: "#2a78d6", accion: "#b3261e", nueva: "#1c6b3a", otro: "#8a8a8a"};
  const esc = (s) =&gt; s.replace(/[&&lt;&gt;]/g, (c) =&gt; ({"&": "&amp;", "&lt;": "&lt;", "&gt;": "&gt;"}[c]));
  let s = `&lt;svg viewBox="0 0 ${W} ${H}" width="100%" style="max-width:600px" role="img" aria-label="Perfil de la charla con ${pts.length} momentos" font-family="inherit"&gt;&lt;line x1="20" x2="${W - 20}" y1="${y.es}" y2="${y.es}" stroke="currentColor" stroke-opacity="0.2" stroke-dasharray="4 4"/&gt;&lt;text x="20" y="${y.es + 16}" font-size="11" fill="currentColor"&gt;lo que es&lt;/text&gt;&lt;line x1="20" x2="${W - 20}" y1="${y.podria}" y2="${y.podria}" stroke="currentColor" stroke-opacity="0.2" stroke-dasharray="4 4"/&gt;&lt;text x="20" y="${y.podria - 6}" font-size="11" fill="currentColor"&gt;lo que podría ser&lt;/text&gt;`;
  s += `&lt;path d="${pts.map((p, i) =&gt; `${i ? "L" : "M"}${x(i)} ${y[p.t]}`).join(" ")}" fill="none" stroke="currentColor" stroke-width="2"/&gt;`;
  pts.forEach((p, i) =&gt; s += `&lt;circle cx="${x(i)}" cy="${y[p.t]}" r="8" fill="${color[p.t]}"/&gt;&lt;text x="${x(i)}" y="${y[p.t] + 4}" font-size="10" fill="#fff" text-anchor="middle" font-weight="700"&gt;${i + 1}&lt;/text&gt;`);
  s += "&lt;/svg&gt;";
  const cambios = pts.slice(1).filter((p, i) =&gt; (p.t === "es") !== (pts[i].t === "es")).length;
  const avisos = [];
  if (!pts.some((p) =&gt; p.t === "accion")) avisos.push("Falta la llamada a la acción: ¿qué quieres que haga el público al salir?");
  if (!pts.some((p) =&gt; p.t === "nueva")) avisos.push("Falta la «nueva normalidad»: cierra describiendo cómo será el mundo si te hacen caso.");
  if (cambios &lt; 3) avisos.push("Hay pocos contrastes entre «lo que es» y «lo que podría ser»: el ritmo de ida y vuelta mantiene la tensión.");
  if (pts.some((p) =&gt; p.t === "otro")) avisos.push("Algunas líneas no empiezan por ES:, PODRÍA:, ACCIÓN: o NUEVA:.");
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `${s}&lt;ol class="small"&gt;${pts.map((p) =&gt; `&lt;li&gt;&lt;span style="color:${color[p.t]};font-weight:600"&gt;${{es: "Es", podria: "Podría ser", accion: "Acción", nueva: "Nueva normalidad", otro: "?"}[p.t]}&lt;/span&gt; · ${esc(p.txt)}&lt;/li&gt;`).join("")}&lt;/ol&gt;${avisos.length ? `&lt;ul&gt;${avisos.map((a) =&gt; `&lt;li&gt;⚠ ${a}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : "&lt;p&gt;✓ Estructura completa: contrastes, llamada a la acción y cierre.&lt;/p&gt;"}`;
  return d;
}
